class Solution {
  public int leastOpsExpressTarget(int x, int target) {
    // digit DP in base x: pos = cost if the current digit is built upwards, neg = if it borrows
    // from the next
    long pos = 0, neg = 0;
    long scale = 1; // x^k
    int k = 0;
    while (target > 0) {
      int digit = target % x;
      target /= x;
      if (k == 0) {
        pos = digit * 2L; // digit copies of x/x
        neg = (x - digit) * 2L;
      } else {
        long nextPos = Math.min(digit * k + pos, (digit + 1) * k + neg);
        long nextNeg = Math.min((x - digit) * k + pos, (x - digit - 1) * k + neg);
        pos = nextPos;
        neg = nextNeg;
      }
      k++;
    }
    return (int) Math.min(pos, k + neg) - 1;
  }
}
